from itertools import permutations

n = 2
# Find permutation of 0..n-1 where absolute differences are permutation of 1..n-1
for perm in permutations(range(n)):
    diffs = [abs(perm[i+1] - perm[i]) for i in range(n-1)]
    if sorted(diffs) == list(range(1, n)):
        # Check fixed assignments
        if perm[0] == 0 and diffs[0] == 1:
            print(f"Solution: {list(perm)}, diffs: {diffs}")
